def Irreflexive (α : Type) (r : α → α → Prop) : Prop :=
  ∀ (a : α), ¬ (r a a)

def Transitive (α : Type) (r : α → α → Prop) : Prop :=
  ∀ (a b c : α), r a b → r b c → r a c

def IsStrictOrder (α : Type) (r : α → α → Prop) : Prop :=
  Irreflexive α r ∧ Transitive α r

def Antisymmetric (α : Type) (r : α → α → Prop) : Prop :=
  ∀ (a b : α), r a b → r b a → a = b

def Irreflexive (α : Type) (r : α → α → Prop) : Prop :=
  ∀ (a : α), ¬ (r a a)

def Function.LeftInverse (α β : Type) (g : β → α) (f : α → β) : Prop :=
  ∀ (x : α), g (f x) = x

def Function.RightInverse (α β : Type) (g : β → α) (f : α → β) : Prop :=
  ∀ (y : β), f (g y) = y

def Function.Inverse (α β : Type) (f : α → β) (g : β → α) : Prop :=
  LeftInverse α β g f ∧ RightInverse α β g f

def Set.InjOn (α β : Type) (f : α → β) (A : Set α) : Prop :=
  ∀ (x : α), x ∈ A → ∀ (y : α), y ∈ A → f x = f y → x = y

def Set.Le (α β : Type) (A : Set α) (B : Set β) : Prop :=
  ∃ (f : α → β), Set.InjOn α β f A ∧ Set.MapsTo α β f A B

def CH : Prop :=
  ∀ (X : Set (Set Nat)), (@Set.univ Nat) ≼ X →
    (@Set.univ Nat) ≈ X ∨ X ≈ (𝒫 (@Set.univ Nat))

def Set.sUnion (α : Type) (F : Set (Set α)) : Set α :=
  fun (x : α) => ∃ (A : Set α), A ∈ F ∧ x ∈ A

def Set.sInter (α : Type) (F : Set (Set α)) : Set α :=
  fun (x : α) => ∀ (A : Set α), A ∈ F → x ∈ A
